"""LY08: real joined handwriting using the learner's taught model."""
import json
from pathlib import Path
items=[]
def base(b,q):
 n=sum(x['bank']==b for x in items)+1
 return dict(id=f'AC9E3LY08-{b[0].upper()}-{n:03d}',subject='english',year_level='Year 3',curriculum_code='AC9E3LY08',bank=b,skill='Write clear joined letters of consistent size',question=q,audio_prompt=q,visual={'type':'none'})
def mc(b,t,ask,c,w,why):
 x=base(b,t+'\n\n'+ask);p=sum(y['bank']==b and y.get('grading_mode')!='adult-review' for y in items)%4;opts=w[:];opts.insert(p,c)
 x.update(answers=[{'text':v,'is_correct':i==p} for i,v in enumerate(opts)],correct_index=p,explanation={'summary':why,'hint':'Use the stated observation; no handwriting picture is being shown.'});items.append(x)
def write(b,words,focus,action,criterion):
 q=f'Words to write on paper: {words}.\n\nUse the joined-handwriting model taught in your class. Ask an adult to show the taught joins first if you need a reminder; printed words here show spelling, not handwriting strokes. Write each word with a pencil or pen. {focus} {action} Show your actual handwriting to the adult.'
 x=base(b,q);x.update(grading_mode='adult-review',answers=[],correct_index=None,model_answer=f'The paper sample contains {words}, with recognisable letters, taught joins and consistent relative size. '+criterion,acceptance_note='The adult must inspect the actual paper sample and observe the writing where needed. Check joined writing, clear formation and consistent relative size using the learner’s taught model. Corresponding small letter bodies should be reasonably consistent; tall parts and descenders keep their intended proportions. Follow that model’s pen lifts and non-joins rather than joining every adjacent pair. '+criterion+' A typed copy, checkbox or statement of completion is not evidence of handwriting. Judge the actual forms rather than speed, decoration or one compulsory grip.',response_instructions='Write on paper. Compare your letters with the model you have been taught, then show the sample to an adult. This box can hold a note about the adult’s feedback, but it is not the handwriting sample.',completion_label='My handwritten sample is ready; an adult still needs to check it.',explanation={'summary':'An adult checks the real writing for taught joins, clear forms and consistent relative letter size.','hint':'Use a comfortable pace. Check the actual letters and joins rather than trying to make every letter the same height.'});items.append(x)
mc('practice','Observation: In a handwritten word, the first small o is much larger than the second small o. Both can be recognised.','Which feature needs attention?','Consistent size of the same letter.',['Changing every letter into a capital.','Adding colour to the page.','Replacing the word with a longer one.'],'Two instances of the same small letter should have reasonably consistent size.')
mc('practice','Observation: A learner forces a long connecting stroke between two letters where the taught model uses a pen lift.','What should the learner do?','Follow the taught lift and form the next letter clearly.',['Join every pair regardless of the model.','Remove the second letter completely.','Make both letters as large as the page.'],'Joined handwriting still includes model-specific lifts and non-joins.')
mc('practice','Observation: The rounded part of a handwritten a has not been closed, so a reader mistakes it for u.','Which improvement addresses the problem?','Form the a clearly using the taught model.',['Write the same unclear shape faster.','Change only the colour of the pencil.','Add a decoration beside the word.'],'The difficulty is identifying the letter, so its formation needs attention.')
mc('practice','Observation: A learner joins all the letters but makes the small letters gradually taller across the word.','What should be checked next?','Whether corresponding small letter bodies stay a consistent size.',['Whether every letter has become a different colour.','Whether the word contains enough unusual letters.','Whether the line fills the entire page.'],'Joining alone does not ensure size consistency.')
mc('practice','Observation: The adult can see a typed answer on screen, but no handwritten sample.','What evidence is still needed for this handwriting task?','The learner’s actual handwritten words.',['A statement that typing was quick.','A printed font selected from a menu.','A promise to write another day.'],'Typing does not show the learner’s handwritten letter formation or joins.')
mc('practice','Observation: A learner makes l the same height as the small body of e, although the taught model gives l a taller part.','What does consistent size mean here?','Keep each letter’s intended proportions, not make all letters identical in height.',['Flatten every tall letter to small-letter height.','Make the e taller than the whole word.','Avoid writing any word containing l.'],'Consistency preserves the model’s size relationships between different letters.')
mc('practice','Observation: Two joined n letters have been crowded so closely that the reader cannot tell where one ends.','What is a useful revision?','Rewrite the join and shapes with enough room to recognise both letters.',['Add another n without checking the shapes.','Push the letters even closer together.','Cross out the whole page and stop writing.'],'Clear joined forms still need distinguishable letters.')
mc('practice','Observation: The dot for i has been placed far over the next letter.','Which correction helps the reader?','Put the dot in the taught position above its own i.',['Put a dot over every letter.','Leave the word unchanged because all dots mean the same thing.','Turn the whole word upside down.'],'A correctly positioned dot helps identify the intended letter.')
mc('practice','Observation: A learner writes neatly at first, then rushes and loses clear joins in the final word.','Which practice choice targets the difficulty?','Rewrite the final word at a comfortable pace and check its joins.',['Race to finish even faster.','Practise only the already-clear first word.','Judge the writing only by how long it took.'],'The revision targets the unclear word and does not set an arbitrary speed goal.')
mc('practice','Observation: The joined word is clear, but the next word touches it with no visible gap.','What would help the reader separate the words?','Leave a clear gap between the words.',['Remove all spaces from the line.','Join across the word boundary.','Make the letters unrecognisable to show the boundary.'],'Word spacing keeps separate words readable even when letters within them are joined.')
mc('practice','Observation: An adult points out that a letter faces the opposite direction from the taught model.','What should the learner compare?','The letter’s starting point and movement with the taught form.',['Only the paper’s colour.','Only the total number of words.','Whether the word is the longest on the page.'],'The direction of formation relates to the reversed shape.')
mc('practice','Observation: The learner’s model uses a specific join into e. A different classroom uses another taught join.','Which model should guide this learner’s practice?','The consistent model the learner has been taught.',['A random mixture of both styles within each word.','Any connecting line, even if the letter becomes unclear.','An ordinary italic computer font as proof of pen movement.'],'Practice should use the taught formation sequence, not a font or a mixed guess.')
P='''in, inn, ink|Compare the small letter bodies and make each n distinguishable.|Write each word once, then choose one to rewrite after checking it.|Check the n forms and the taught join into or out of n; do not accept an extra or missing hump that changes the word.
minimum, mint, mine|Keep the m and n shapes distinct rather than letting their strokes merge.|Underline the clearest word and rewrite another if needed.|Check repeated short strokes remain identifiable with consistent small-body size.
ill, hill, little|Compare repeated l shapes and their height in your taught model.|Write the set, then compare the first and last l in your sample.|Check tall parts keep their intended height while smaller letter bodies remain smaller.
moon, noon, room|Keep the rounded letters clear when moving into the next letter.|Circle one clear round letter and improve an unclear one if present.|Check each o remains recognisable and comparable in size.
can, cane, came|Watch the change from n to m and the final e.|Write the three words and ask the adult to read them without your help.|Check the ending and middle letters can be distinguished from the paper sample.
rain, train, grain|Keep the small bodies steady as the word gains more letters.|Compare rain inside all three words after writing.|Check the repeated letter sequence has consistent relative size across different word lengths.
line, lime, time|Use the taught joins while keeping n and m distinct.|Write each word twice and compare corresponding letters.|Check the repeated samples maintain clear letter identity rather than merely matching total word length.
seed, need, feed|Keep both e letters recognisable, following any lifts in the model.|Choose the clearest ee pair and use it to guide one revision.|Check the repeated e letters have clear openings and consistent body size; follow the model’s treatment of f.
coat, coal, cold|Compare the beginnings and then the different endings.|Write the set and point to each changed ending.|Check clear c and o forms plus distinct t, l and d endings as taught.
hand, band, land|Make the tall parts and rounded bodies match their intended proportions.|Compare the initial letters before rewriting one word.|Check h, b and l are distinguishable and not compressed to small-body height.
play, plan, plane|Keep the shared pla sequence clear before the endings change.|Write the three words and check the y against your model.|Check joins do not remove the intended descender in y or blur n and e.
sing, ring, wing|Allow space for the g below the writing line if your model uses it.|Compare the three g forms and improve one if needed.|Check consistent g formation and relative size across the three words.
jump, pump, lump|Keep the lower parts of j or p clear without stretching nearby letters.|Write the set, then compare the p letters across pump and lump.|Check descenders and small bodies retain their taught proportions.
quick, quiet, quilt|Use the taught q form and the following join or lift.|Write all three and compare the beginning qu.|Check q is identifiable and its relation to u follows the taught model.
wave, weave, wire|Pay attention to w and its transition into the next letter.|Choose one word for a second careful copy.|Check w remains distinct and joins do not close or distort the following letter.
very, over, river|Compare r in different positions within words.|Write the set, then ask the adult to identify each r.|Check model-specific r formation remains clear at the different positions.
open, oval, oven|Use the same small-body height for the round letters.|Write each word once and compare the starting o shapes.|Check o and the following letters keep separate identities within the joined word.
blue, clue, glue|Keep the tall l and the smaller u and e proportionate.|Write the set, then compare the shared lue sequence.|Check tall and short components keep their intended relative sizes.
sun, sand, send|Check the taught shape and joining treatment of s.|Write each word and compare the starting s forms.|Check s remains recognisable; do not force a join absent from the taught model.
soft, left, lift|Follow the model’s treatment of f and t, including any cross strokes or lifts.|Write each word, then check the final two letters.|Check the f and t forms are clear and consistent with the taught sequence, not one universal joining rule.
back, bank, bark|Keep the k shape distinct from the letters before it.|Write the set and check whether an adult can tell the three words apart.|Check the middle c/n/r and final k remain clear.
box, wax, mix|Use the taught pen movement and any lift for x.|Write each word, then compare the three final x letters.|Check x remains identifiable and matches the model’s treatment of joining or lifting.
zip, zebra, zero|Use the taught z shape rather than copying a computer font’s strokes.|Write the words and compare their starting letters.|Check consistent z formation and relative size across short and longer words.
bag, dad, gap|Distinguish b, d and g by following their taught formation.|Write the set and ask the adult to name the starting letters.|Check orientation and recognisable forms, not only the presence of joins.
meadow, window, shadow|Keep the size steady through each longer word.|Compare the beginning and ending small letters after writing.|Check that letters do not gradually enlarge or shrink across a longer word.
rabbit, ribbon, rubble|Keep doubled letters distinct while using taught joins.|Write the words and compare the doubled b forms.|Check both b letters remain visible with appropriate tall parts.
letter, better, little|Check repeated t and l forms against the model.|Write the set and choose one pair to revise if needed.|Check cross strokes, tall parts and small letter bodies remain clear.
bubble, bottle, paddle|Keep rounded bodies clear beside repeated tall letters.|Write the words and compare the final le groups.|Check the final e stays recognisable and tall-letter proportions are maintained.
pretty, happy, puppy|Make repeated letters clear and keep y proportionate.|Write the set and compare the final y shapes.|Check each doubled-letter sequence and the taught y ending.
small shell, smooth stone|Keep letters joined within the taught pattern but leave clear word gaps.|Write both phrases, then point to the spaces between words.|Check the four words are separately readable and letter size stays steady.
bright kite, blue boat|Keep tall and small letters in proportion across each phrase.|Write both phrases and compare the starting b shapes.|Check consistent relative size and legibility in a phrase, not only an isolated word.
green gate, quiet garden|Allow room for descenders and use clear word spacing.|Write the phrases on separate lines and compare their g forms.|Check the lower parts do not collide with the next line and the model’s joins remain clear.
paper plane, pencil case|Keep the shared p forms clear in different words.|Write both labels and compare the starting letters.|Check p is identifiable with consistent relative size, and spaces preserve the two-word labels.
water wheel, wooden wall|Compare repeated w and l shapes across the labels.|Write the labels, then improve one inconsistent letter if needed.|Check corresponding shapes are consistent while each word stays readable.
little lantern, silver bell|Keep small bodies consistent beside tall strokes.|Write both labels and ask the adult to read them from your page.|Check joined handwriting remains legible through longer word groups.
round pond, sandy path|Keep round letters distinct and descenders proportionate.|Write both labels, compare with the taught model and make one useful revision if needed.|Check actual letter formation, joins and relative size across the full sample.
'''
for row in P.strip().splitlines():write('practice',*row.split('|'))
mc('test','Observation: Three copies of the same word are joined. In one copy, two letters merge so the adult reads a different word.','Which feature needs correcting in that copy?','The clarity of the merged letter forms.',['The number of colours used.','The length of the page.','The fact that the word was copied more than once.'],'A join should not make the intended letters unreadable.')
mc('test','Observation: All small a letters on a line are clear, but each successive a is much larger than the one before.','What is the most relevant improvement?','Keep the corresponding small letter bodies a consistent size.',['Make every tall letter shorter than a.','Add extra words without checking size.','Use more decorative lines around the sample.'],'The stated difficulty is inconsistency among corresponding letters.')
mc('test','Observation: The taught model lifts the pen before a letter. A learner follows that lift and writes the whole word clearly with other taught joins.','How should this be judged?','The model’s planned lift is compatible with joined handwriting.',['Every pen lift automatically makes the word wrong.','Only a word drawn in one unbroken stroke can be joined.','The learner must invent a connection at every boundary.'],'Taught cursive patterns can contain deliberate lifts and non-joins.')
mc('test','Observation: A learner submits only the sentence “My handwriting is neat”.','What should the adult request before judging this handwriting task?','The actual handwritten target words.',['A second typed claim using larger text.','A faster spoken answer.','A different colour for the screen background.'],'The written letter forms and joins must be inspected directly.')
T='''ripple, riddle, middle|Keep the doubled letters distinct and the final e clear.|Write each word once; compare and revise only where needed.|Check repeated letters, taught joins and steady relative size in the actual sample.
quietly, quickly, quilted|Check the q beginning and the tall and lower parts throughout.|Write the set and compare matching letters.|Check clear q and its taught relation to the following u without shrinking later letters.
golden, garden, gentle|Compare the g forms and keep the small letter bodies proportionate.|Write the three words and ask the adult to read each.|Check consistent g formation and recognisable differences in the remaining letters.
shadow, shower, shining|Use the taught s and h forms and maintain size through the longer words.|Write the set, then compare its first and last small letters.|Check stable size and clear word identity across the sample.
feather, softer, lifting|Follow your model for f and t, including planned lifts and cross strokes.|Write each word and inspect the relevant pairs.|Check model-appropriate forms rather than imposing the same join on every f/t combination.
woven, winter, waiting|Keep w and the following letters distinct.|Write the set and compare the repeated starting shape.|Check recognisable w and consistent small-body size through each word.
bright bridge, broad branch|Keep b and r clear next to each other and preserve word gaps.|Write both phrases and ask the adult to read them.|Check legibility, repeated shapes and clear separation of the words.
purple paper, tiny puppy|Check the p shapes and the size of surrounding small letters.|Write the phrases and compare the p forms.|Check intended lower parts and clear repeated letters in puppy.
clear cloud, small circle|Keep rounded letters recognisable beside tall strokes.|Write both labels and compare them with the taught model.|Check the joined forms keep the distinct identities of c, l and other letters.
empty box, open basket|Use the taught x and b formations with their lifts or joins.|Write both labels and check one target letter in each.|Check correct orientation and consistent relative size, with readable word gaps.
silver river, narrow road|Compare r in different positions and keep small bodies steady.|Write both phrases and make a needed revision if the adult identifies one.|Check the taught r shape remains recognisable in the different contexts.
little window, yellow lantern|Keep repeated l forms steady while other letters keep their own proportions.|Write the labels on two lines and compare the full sample.|Check clear joins, intended tall parts and consistent size through both lines.
'''
for row in T.strip().splitlines():write('test',*row.split('|'))
assert len(items)==64
assert sum(x['bank']=='practice' for x in items)==48
Path(__file__).with_name('ac9e3ly08.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
